-- mod-subclass: copies of class spells whose animation leaves the casting arm alone, sent when the other head casts them.

DROP TABLE IF EXISTS `mod_subclass_other_head_spell`;
CREATE TABLE `mod_subclass_other_head_spell` (
    `SpellId` INT UNSIGNED NOT NULL,
    `ShownId` INT UNSIGNED NOT NULL,
    PRIMARY KEY (`SpellId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
